import path from 'path';

export interface ProjectStorageLocation {
  dataDirectory: string;
  cacheDirectory: string;
}

interface ProjectStorageAttachment extends ProjectStorageLocation {
  projectPath: string;
}

export class ProjectStorage {
  private readonly locations: Map<string, ProjectStorageLocation>;

  constructor(attachments: readonly ProjectStorageAttachment[] = []) {
    this.locations = new Map(
      attachments.map(({ projectPath, dataDirectory, cacheDirectory }) => [
        path.resolve(projectPath),
        {
          dataDirectory: path.resolve(dataDirectory),
          cacheDirectory: path.resolve(cacheDirectory),
        },
      ]),
    );
  }

  attach({
    projectPath,
    dataDirectory,
    cacheDirectory,
  }: ProjectStorageAttachment): void {
    this.locations.set(path.resolve(projectPath), {
      dataDirectory: path.resolve(dataDirectory),
      cacheDirectory: path.resolve(cacheDirectory),
    });
  }

  isAttached(projectPath: string): boolean {
    return this.locations.has(path.resolve(projectPath));
  }

  resolve(projectPath: string): ProjectStorageLocation {
    const root = path.resolve(projectPath);
    return (
      this.locations.get(root) ?? {
        dataDirectory: path.join(root, '.rivet'),
        cacheDirectory: path.join(root, '.rivet', 'cache'),
      }
    );
  }
}
